/** Local root metadata only; actual source drift remains fatal and the server is never written. */
import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{alignOwnedSourceRootTime}from'./source-root-time.mjs';import{cleanHead}from'./release-ci.mjs';
export function arrivalProbeProgram(grant){return `import fs from'node:fs';import{execFileSync}from'node:child_process';import{fingerprintStagingEnvironment}from'./.github/ci/staging-environment.mjs';import{readPrivateInstall}from'./.github/ci/staging-build-install.mjs';const root='/opt/ai-hr',p=readPrivateInstall(${JSON.stringify(grant.installId)});const state=Object.fromEntries(fs.readFileSync('/var/tmp/aihr-deploy/current','utf8').split(String.fromCharCode(10)).filter(l=>l.includes('=')).map(l=>{const i=l.indexOf('=');return[l.slice(0,i),l.slice(i+1)]}));const runtime=JSON.parse(fs.readFileSync(p.directory+'/runtime.json'));const active=fs.lstatSync(root+'/.next',{bigint:true}),s=fs.lstatSync(root,{bigint:true});if(fs.realpathSync(root)!==root||!s.isDirectory()||s.isSymbolicLink())throw Error('Actual root directory required');console.log(JSON.stringify({directory:{device:String(s.dev),inode:String(s.ino),uid:String(s.uid),gid:String(s.gid),mode:Number(s.mode&511n),mtimeNs:String(s.mtimeNs)},source:state.ref,result:state.result,buildId:fs.readFileSync(root+'/.next/BUILD_ID','utf8').trim(),environmentSha256:fingerprintStagingEnvironment(root),pid:execFileSync('systemctl',['show','aihr','--property=MainPID','--value'],{encoding:'utf8'}).trim(),service:execFileSync('systemctl',['is-active','aihr'],{encoding:'utf8'}).trim(),runtimeSource:runtime.source,runtimeBuild:runtime.nextBuildId,runtimePid:runtime.pid,installId:p.grant.installId,grantSource:p.grant.source,activeDirectory:{device:String(active.dev),inode:String(active.ino)}}));`;}
export function alignCandidateRootAfterInstall({candidatePath,grant,ssh,checksum,save}){
 const code=arrivalProbeProgram(grant);
 return alignOwnedSourceRootTime({source:candidatePath,readDiff:checksum,readRemote:()=>JSON.parse(ssh('cd /opt/ai-hr && /opt/node22/bin/node --input-type=module',{input:code,timeout:30000})),verifyRemote:r=>{assert(r.source===grant.source&&r.result==='ok'&&r.buildId===grant.build.nextBuildId&&r.environmentSha256===grant.environmentSha256&&r.service==='active'&&/^[1-9][0-9]*$/.test(r.pid)&&r.pid===r.runtimePid&&r.runtimeSource===grant.source&&r.runtimeBuild===grant.build.nextBuildId&&r.installId===grant.installId&&r.grantSource===grant.source&&r.directory.uid==='1000'&&r.directory.gid==='1000','Actual installed source/runtime/configuration required for local metadata alignment');},verifySource:()=>{const ref=cleanHead(candidatePath);assert(ref===grant.source,'Exact installed source required');return{ref,tree:execFileSync('git',['-C',candidatePath,'rev-parse','HEAD^{tree}'],{encoding:'utf8'}).trim()};},save:p=>save('local-source-root-time-alignment.json',p)});
}
